#!/usr/bin/env python3
"""
Generate PowerPoint presentations for AI for Drug Discovery course (Weeks 1-4).
Run: python generate_slides.py
Requirements: pip install python-pptx
"""
import os
from pptx import Presentation
from pptx.util import Inches, Pt, Emu
from pptx.dml.color import RGBColor
from pptx.enum.text import PP_ALIGN, MSO_ANCHOR
from pptx.enum.shapes import MSO_SHAPE

NAVY = RGBColor(23, 55, 94)
TEAL = RGBColor(31, 119, 180)
DARK_SLATE = RGBColor(44, 62, 80)
WHITE = RGBColor(255, 255, 255)
LIGHT_GRAY = RGBColor(240, 240, 240)
BODY_TEXT = RGBColor(50, 50, 50)
ACCENT_GREEN = RGBColor(39, 174, 96)
SLIDE_WIDTH = Inches(13.333)
SLIDE_HEIGHT = Inches(7.5)

def new_prs():
    prs = Presentation()
    prs.slide_width = SLIDE_WIDTH
    prs.slide_height = SLIDE_HEIGHT
    return prs

def _add_bg(slide, color):
    fill = slide.background.fill
    fill.solid()
    fill.fore_color.rgb = color

def _add_textbox(slide, left, top, width, height, text, font_size=18, bold=False, color=BODY_TEXT, alignment=PP_ALIGN.LEFT):
    txBox = slide.shapes.add_textbox(left, top, width, height)
    tf = txBox.text_frame
    tf.word_wrap = True
    p = tf.paragraphs[0]
    p.text = text
    p.font.size = Pt(font_size)
    p.font.bold = bold
    p.font.color.rgb = color
    p.font.name = "Calibri"
    p.alignment = alignment
    return tf

def _add_slide_number(slide, num):
    _add_textbox(slide, Inches(12.3), Inches(7.0), Inches(0.8), Inches(0.4), str(num), font_size=10, color=RGBColor(150,150,150), alignment=PP_ALIGN.RIGHT)

def _add_bullets(tf, bullets, font_size=18, color=BODY_TEXT):
    for i, bullet in enumerate(bullets):
        if i == 0:
            p = tf.paragraphs[0]
        else:
            p = tf.add_paragraph()
        p.text = bullet
        p.font.size = Pt(font_size)
        p.font.color.rgb = color
        p.font.name = "Calibri"
        p.space_after = Pt(8)

def _set_notes(slide, notes_text):
    slide.notes_slide.notes_text_frame.text = notes_text

def make_title_slide(prs, title, subtitle, week_num, course_name, notes):
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    _add_bg(slide, NAVY)
    _add_textbox(slide, Inches(0.8), Inches(0.6), Inches(3), Inches(0.6), f"WEEK {week_num}", font_size=16, bold=True, color=TEAL)
    _add_textbox(slide, Inches(0.8), Inches(1.8), Inches(11), Inches(2), title, font_size=44, bold=True, color=WHITE)
    _add_textbox(slide, Inches(0.8), Inches(4.0), Inches(11), Inches(1), subtitle, font_size=22, color=LIGHT_GRAY)
    _add_textbox(slide, Inches(0.8), Inches(6.2), Inches(5), Inches(0.5), course_name, font_size=14, color=TEAL)
    _set_notes(slide, notes)

def make_section_divider(prs, section_title, slide_num, notes, subtitle=""):
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    _add_bg(slide, TEAL)
    _add_textbox(slide, Inches(1), Inches(2.5), Inches(11), Inches(1.5), section_title, font_size=40, bold=True, color=WHITE, alignment=PP_ALIGN.CENTER)
    if subtitle:
        _add_textbox(slide, Inches(1), Inches(4.2), Inches(11), Inches(1), subtitle, font_size=20, color=WHITE, alignment=PP_ALIGN.CENTER)
    _add_slide_number(slide, slide_num)
    _set_notes(slide, notes)

def make_content_slide(prs, title, bullets, slide_num, notes):
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    shape = slide.shapes.add_shape(MSO_SHAPE.RECTANGLE, 0, 0, SLIDE_WIDTH, Inches(1.1))
    shape.fill.solid()
    shape.fill.fore_color.rgb = NAVY
    shape.line.fill.background()
    _add_textbox(slide, Inches(0.6), Inches(0.15), Inches(12), Inches(0.8), title, font_size=28, bold=True, color=WHITE)
    txBox = slide.shapes.add_textbox(Inches(0.8), Inches(1.4), Inches(11.5), Inches(5.5))
    tf = txBox.text_frame
    tf.word_wrap = True
    _add_bullets(tf, bullets, font_size=20, color=BODY_TEXT)
    _add_slide_number(slide, slide_num)
    _set_notes(slide, notes)

def make_two_column_slide(prs, title, left_title, left_bullets, right_title, right_bullets, slide_num, notes):
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    shape = slide.shapes.add_shape(MSO_SHAPE.RECTANGLE, 0, 0, SLIDE_WIDTH, Inches(1.1))
    shape.fill.solid()
    shape.fill.fore_color.rgb = NAVY
    shape.line.fill.background()
    _add_textbox(slide, Inches(0.6), Inches(0.15), Inches(12), Inches(0.8), title, font_size=28, bold=True, color=WHITE)
    _add_textbox(slide, Inches(0.8), Inches(1.3), Inches(5.5), Inches(0.5), left_title, font_size=22, bold=True, color=TEAL)
    txL = slide.shapes.add_textbox(Inches(0.8), Inches(1.9), Inches(5.5), Inches(5))
    tfL = txL.text_frame; tfL.word_wrap = True
    _add_bullets(tfL, left_bullets, font_size=18)
    _add_textbox(slide, Inches(7.0), Inches(1.3), Inches(5.5), Inches(0.5), right_title, font_size=22, bold=True, color=TEAL)
    txR = slide.shapes.add_textbox(Inches(7.0), Inches(1.9), Inches(5.5), Inches(5))
    tfR = txR.text_frame; tfR.word_wrap = True
    _add_bullets(tfR, right_bullets, font_size=18)
    _add_slide_number(slide, slide_num)
    _set_notes(slide, notes)

def make_discussion_slide(prs, question, context_bullets, slide_num, notes):
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    _add_bg(slide, DARK_SLATE)
    _add_textbox(slide, Inches(1), Inches(0.5), Inches(11), Inches(0.6), "DISCUSSION QUESTION", font_size=18, bold=True, color=TEAL)
    _add_textbox(slide, Inches(1), Inches(1.5), Inches(11), Inches(2), question, font_size=30, bold=True, color=WHITE, alignment=PP_ALIGN.CENTER)
    if context_bullets:
        txBox = slide.shapes.add_textbox(Inches(1.5), Inches(4.0), Inches(10), Inches(3))
        tf = txBox.text_frame; tf.word_wrap = True
        _add_bullets(tf, context_bullets, font_size=18, color=LIGHT_GRAY)
    _add_slide_number(slide, slide_num)
    _set_notes(slide, notes)

def make_takeaway_slide(prs, takeaways, week_num, slide_num, notes):
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    _add_bg(slide, NAVY)
    _add_textbox(slide, Inches(1), Inches(0.5), Inches(11), Inches(0.8), f"KEY TAKEAWAYS - WEEK {week_num}", font_size=28, bold=True, color=WHITE, alignment=PP_ALIGN.CENTER)
    txBox = slide.shapes.add_textbox(Inches(1.5), Inches(1.8), Inches(10), Inches(5))
    tf = txBox.text_frame; tf.word_wrap = True
    _add_bullets(tf, takeaways, font_size=22, color=WHITE)
    _add_slide_number(slide, slide_num)
    _set_notes(slide, notes)

def make_story_slide(prs, title, story_text, slide_num, notes):
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    _add_bg(slide, DARK_SLATE)
    _add_textbox(slide, Inches(1), Inches(0.5), Inches(11), Inches(0.7), title, font_size=26, bold=True, color=ACCENT_GREEN)
    _add_textbox(slide, Inches(1.2), Inches(1.6), Inches(10.5), Inches(5.2), story_text, font_size=20, color=WHITE)
    _add_slide_number(slide, slide_num)
    _set_notes(slide, notes)


# ===== WEEK 1 =====
def generate_week1():
    prs = new_prs()
    n = 0
    n += 1
    make_title_slide(prs, "Introduction & The Drug Discovery Pipeline", "From bench to bedside - and how AI is rewriting the rules", 1, "AI for Drug Discovery", notes="Welcome everyone to AI for Drug Discovery! Take a moment to introduce yourself and your background.\n\n=== ABOUT YOUR INSTRUCTOR ===\nDr. Étienne Serbe-Kamp is a neuroscientist with a research background in computational and systems neuroscience, specifically in Drosophila (fruit fly) visual motion detection circuits. His key publications include:\n- 'Multilevel visual motion opponency in Drosophila' (Nature Neuroscience, 2023) - discovered how GluClα-mediated inhibition creates direction-selective motion opponency across three network levels\n- 'Voltage to Calcium Transformation Enhances Direction Selectivity in Drosophila T4 Neurons' (J. Neurosci., 2023)\n- 'Comprehensive Characterization of the Major Presynaptic Elements to the Drosophila OFF Motion Detector' (Neuron, 2016)\n- 'A Directional Tuning Map of Drosophila Elementary Motion Detectors' (Nature, 2013)\n\nHe is also Co-Director of Summer Fellowships at Backyard Brains, where he develops open-source neuroscience tools (SpikerBox/SpikerBot) and leads citizen science projects including 'A Library of Electrophysiological Responses in Plants' (2024) and the ERGo! platform for electroretinogram recording.\n\nWhy is a neuroscientist teaching drug discovery? Because the tools are the same! The computational pipeline (signal -> features -> model -> prediction) is identical whether you are studying neural circuits, molecular properties, or physiological signals. And many of the most important drug targets in the world are proteins that Dr. Serbe-Kamp studies directly: ion channels, neurotransmitter receptors, and synaptic signaling molecules.\n\nTell the class: this course will blend neuroscience, pharmacology, and AI/ML. We will use real neuroscience examples alongside drug discovery, because understanding the biology of drug targets makes you a better computational scientist.")
    n += 1
    make_content_slide(prs, "Course Roadmap - 7 Weeks + Project", ["Week 1: Introduction & Drug Discovery Pipeline (TODAY)", "Week 2: Molecular Representation & Baseline ML", "Week 3: Model Evaluation & Interpretability", "Week 4: Deep Learning & Graph Neural Networks", "Week 5: Generative AI for Molecule Design", "Week 6: Protein Targets & Binding Prediction", "Week 7: Ethics, Regulation & Project Workshop", "Week 8: Group Project Exam (Presentation + Code + Report)", "", "Assessment: Implementation 40% | Scientific reasoning 25% | Evaluation 20% | Presentation 15%"], n, notes="Walk through the roadmap quickly, about 2 minutes. Emphasize that the course is hands-on: every week has a practical coding session. Tell students they will work in groups of 3-4 for the final project and can choose from QSAR prediction, GNN-based activity prediction, generative molecule design, or binding affinity modeling. Groups should start forming informally over the next few weeks. All code will be in Python and Jupyter notebooks, primarily using RDKit, scikit-learn, PyTorch, and DeepChem. No prior chemistry knowledge is required.")
    n += 1
    make_content_slide(prs, "The Brutal Reality of Drug Discovery", ["Average time to market: 12-15 years", "Average cost: $2.6 billion per approved drug (DiMasi et al., 2016, J. Health Economics)", "Success rate from Phase I to approval: ~7.9% (Wong et al., 2019, Biostatistics)", "Over 90% of drug candidates fail in clinical trials", "Only ~14% of drugs entering Phase I get FDA approval", "", "\"The most expensive experiment in science is a failed clinical trial.\""], n, notes="Spend 3-4 minutes here. Let these numbers sink in. Ask students: does anyone know how much a single Phase III clinical trial costs? Answer: $50-100M+. The DiMasi 2016 study in the Journal of Health Economics is the landmark reference for drug development costs. The Wong et al. 2019 paper in Biostatistics analyzed 406,038 entries from ClinicalTrials.gov. Point out that for every drug that reaches patients, thousands of candidates were tested and discarded. This is why even small improvements in efficiency from AI could save billions. Transition: So where exactly does it go wrong?")
    n += 1
    make_content_slide(prs, "Traditional Drug Discovery Pipeline", ["1. TARGET IDENTIFICATION - Find a biological target (protein, enzyme, receptor)", "2. TARGET VALIDATION - Confirm the target is relevant to the disease", "3. HIT DISCOVERY - Screen millions of compounds (High-Throughput Screening)", "4. LEAD OPTIMIZATION - Improve hits for potency, selectivity, ADMET", "5. PRECLINICAL - Animal studies for safety and efficacy", "6. PHASE I - Safety in healthy volunteers (20-100 people)", "7. PHASE II - Efficacy in patients (100-300 people)", "8. PHASE III - Large-scale trials (1,000-3,000+ people)", "9. FDA REVIEW & APPROVAL", "10. POST-MARKET SURVEILLANCE (Phase IV)"], n, notes="Walk through each step in 4-5 minutes. At HIT DISCOVERY, mention that traditional HTS screens 1-2 million compounds physically, incredibly expensive. At LEAD OPTIMIZATION, mention that medicinal chemists manually tweak molecules, this is where AI has huge potential. ADMET stands for Absorption, Distribution, Metabolism, Excretion, Toxicity. Finding a drug is like finding a needle in a haystack, except the haystack is the size of a galaxy. Chemical space is estimated at 10^60 drug-like molecules. Transition: So what goes wrong?")
    n += 1
    make_two_column_slide(prs, "Where Drug Candidates Fail", "Clinical Failure Reasons", ["Lack of efficacy: ~40-50%", "Safety / toxicity: ~30%", "Poor pharmacokinetics: ~10%", "Commercial reasons: ~10%", "Other: ~5%"], "Infamous Failures (incl. CNS drugs)", ["Vioxx (rofecoxib) - withdrawn 2004, cardiac risk", "Thalidomide (1960s) - birth defects (teratogenicity)", "BIA 10-2474 (2016) - Phase I death (FAAH inhibitor, CNS target)", "Eli Lilly semagacestat - worsened Alzheimer's symptoms", "~99.6% Alzheimer's drug candidates fail (Cummings et al. 2014)"], n, notes="Spend 3-4 minutes here. The left column shows aggregate statistics from Kola & Landis (2004, Nature Reviews Drug Discovery).\n\n=== NEUROSCIENCE CONNECTION ===\nCNS (central nervous system) drugs have the HIGHEST failure rate of any therapeutic area. Alzheimer's disease is the most dramatic example: Cummings et al. (2014, Alzheimer's Research & Therapy 6:37) found a 99.6% failure rate for Alzheimer's drugs between 2002-2012. Only memantine (NMDA receptor antagonist) was approved in that decade.\n\nWhy do CNS drugs fail so much?\n1. The blood-brain barrier (BBB) blocks most molecules from reaching brain targets. A drug must be lipophilic enough to cross the BBB but not so lipophilic that it accumulates in fat tissue.\n2. Brain targets are complex: GPCRs, ion channels, and transporters often have many subtypes. Selectivity is hard.\n3. Animal models poorly predict human CNS drug response. A mouse brain is not a human brain.\n4. Biomarkers for CNS diseases (Alzheimer's, Parkinson's, depression) are limited, making it hard to measure efficacy early.\n\nBIA 10-2474 is a chilling example: a FAAH (fatty acid amide hydrolase) inhibitor being tested for pain and mood disorders. In a Phase I trial in Rennes, France (2016), one healthy volunteer died and five were hospitalized with brain damage. FAAH breaks down endocannabinoids in the brain. The drug likely had off-target effects on other lipases in the brain. This underscores why understanding neuroscience targets deeply is critical for drug safety.\n\nThe Drosophila connection: fruit fly neuroscience research helps us understand fundamental neural signaling mechanisms (ion channels, neurotransmitter receptors) that are drug targets in humans. Dr. Serbe-Kamp's work on GluClα channels in the fly visual system directly relates to the GluCl family that is targeted by ivermectin, one of the most important drugs in history.")
    n += 1
    make_story_slide(prs, "David Willson's mRNA Vaccine for His Dog", "In 2024, David Willson's beloved dog was diagnosed with cancer.\n\nRather than accept the prognosis, Willson worked with his veterinarian to design a personalized mRNA vaccine targeting his dog's specific tumor antigens.\n\nThe approach: sequence the tumor, identify neoantigens, design mRNA encoding those antigens, and inject it to train the dog's immune system.\n\nThe story went viral, sparking global conversation about personalized medicine.\n\nThis is the same technology behind COVID-19 vaccines (Moderna, BioNTech/Pfizer) now being applied to individual patients and even pets.\n\nKey insight: The tools for personalized medicine are becoming accessible. AI accelerates every step, from neoantigen prediction to vaccine design.", n, notes="This is your hook story, spend 4-5 minutes here and make it personal. David Willson's story went viral in 2024. He leveraged mRNA technology to create a personalized cancer vaccine for his dog, working with his veterinarian. The point is NOT that everyone should make DIY vaccines, there are serious safety and regulatory considerations. The point IS that the fundamental technologies (sequencing, mRNA design, neoantigen prediction) are becoming accessible and affordable. AI plays a role at every step: predicting which neoantigens will elicit an immune response, optimizing mRNA sequences for stability and expression, and modeling immune responses. Connect this to the course: by the end, students will understand the AI/ML methods that power these advances.")
    n += 1
    make_section_divider(prs, "Enter AI: The Game Changer", n, notes="Quick transition slide, 30 seconds. Tell students: we have seen the problem. It is slow, expensive, and risky. Now let us see how AI is fundamentally changing the game. Major pharma companies (Pfizer, Novartis, AstraZeneca, Roche) are all investing heavily in AI. Startups like Insilico Medicine, Recursion Pharmaceuticals, and Isomorphic Labs are dedicated AI drug discovery companies.", subtitle="How machine learning is reshaping pharmaceutical R&D")
    n += 1
    make_content_slide(prs, "Where AI Fits in the Drug Discovery Pipeline", ["Target Identification - NLP on literature, network biology, multi-omics, connectomics", "Virtual Screening - Score millions of compounds in silico (vs. months in HTS)", "Lead Optimization - Predict ADMET, suggest modifications, multi-objective optimization", "De novo Drug Design - Generate entirely new molecules with desired properties", "Clinical Trial Optimization - Patient stratification, endpoint prediction", "Repurposing - Find new uses for existing drugs (e.g., ivermectin: antiparasitic -> anticancer?)", "", "Neuroscience example: AI on the Drosophila connectome identifies new neural targets", "AI can reduce timelines by 2-4 years and costs by 30-50% (McKinsey, 2021)"], n, notes="Spend 4-5 minutes on this slide. Go through each bullet with examples, and highlight the neuroscience connection wherever possible.\n\n=== NEUROSCIENCE-SPECIFIC AI APPLICATIONS ===\n\n1. TARGET IDENTIFICATION from connectomics:\nThe complete Drosophila brain connectome (Dorkenwald et al. 2024, Nature) mapped ~140,000 neurons and ~50 million synapses. AI/ML is used to analyze this graph to identify cell types, predict function, and find potential drug targets. The same approach is being applied to the mouse brain connectome and will eventually reach human-scale. In Dr. Serbe-Kamp's research area, connectomics has been essential for mapping the visual motion detection circuit: identifying which neurons connect to T4/T5 motion-detecting cells and understanding the synaptic input patterns (Takemura et al. 2013, Nature; Shinomiya et al. 2019, eLife).\n\n2. VIRTUAL SCREENING for CNS drugs:\nScreening compounds for blood-brain barrier penetration is a critical step for CNS drugs. AI models predict BBB permeability from molecular features. DeepBBB (Shaker et al. 2021) uses deep learning. This saves enormous time vs. experimental permeability assays.\n\n3. LEAD OPTIMIZATION for ion channel drugs:\nMany drugs target ion channels that are central to neuroscience: Nav channels (anti-epileptics), GABA-A (anxiolytics), nAChR (nicotine addiction). AI can predict selectivity between channel subtypes, which is crucial to avoid side effects.\n\n4. REPURPOSING with neuroscience insights:\nIvermectin was originally an antiparasitic drug (targets GluCl channels in parasites). It is now being investigated for anticancer properties and has shown activity against various cancers in preclinical studies. BenevolentAI identified baricitinib (a JAK inhibitor) for COVID-19 in Feb 2020. Repurposing leverages existing safety data to fast-track drugs.\n\n5. CONNECTOMICS + AI:\nThe Drosophila connectome is a GRAPH with neurons as nodes and synapses as edges. Graph neural networks (which we will study in Week 4) can be directly applied to this data. Zeng et al. (2023, Cell Reports Methods) used GNNs on connectomics data to predict neuron types and circuit function.")
    n += 1
    make_content_slide(prs, "Case Study: Insilico Medicine ISM001-055", ["First AI-designed drug to reach Phase II clinical trials (2023)", "Target: Idiopathic Pulmonary Fibrosis (IPF)", "AI identified a novel target (TNIK) AND designed the molecule", "Timeline: Target to preclinical candidate in 18 months (vs. typical 4-5 years)", "Cost: ~$2.6M (vs. typical $100M+)", "Published: Ren et al. (2024), Chemical Science", "", "Key AI methods used:", "  PandaOmics - target identification from multi-omics data", "  Chemistry42 - generative chemistry for molecule design", "  InClinico - clinical trial outcome prediction"], n, notes="Spend 3-4 minutes on this landmark case. Insilico Medicine, founded by Alex Zhavoronkov, is based in Hong Kong. ISM001-055 targets TNIK (TRAF2 and NCK-interacting kinase), a novel target for IPF that was not previously known to be relevant. The AI both discovered the target AND designed the drug, end-to-end AI-driven discovery. The cost comparison is staggering: $2.6M vs. $100M+. Ren F. et al. (2024) Chemical Science. Ask: what do you think the biggest challenge is in translating AI-designed drugs to the clinic?")
    n += 1
    make_content_slide(prs, "AlphaFold2: The Protein Folding Revolution", ["Protein structure prediction - a 50-year grand challenge in biology", "CASP14 (2020): AlphaFold2 achieved accuracy comparable to experimental methods", "Jumper et al. (2021), Nature - 2024 Nobel Prize in Chemistry", "", "Impact on drug discovery & neuroscience:", "  200+ million protein structures predicted (AlphaFold DB)", "  Ion channels, GPCRs, neurotransmitter receptors now have predicted structures", "  Structure-based drug design for CNS targets (hERG, GABA-A, GluCl, nAChR)", "", "AlphaFold3 (2024): predicts protein-ligand, protein-DNA, protein-RNA complexes", "Neuroscience example: AlphaFold predicted the GluCl receptor structure", "  (same channel family Dr. Serbe-Kamp studies in Drosophila motion vision!)"], n, notes="AlphaFold is probably the most famous AI success story in biology. Spend 3 minutes here.\n\n=== KEY DETAILS ===\nJumper J. et al. (2021) Highly accurate protein structure prediction with AlphaFold, Nature 596:583-589. Won the 2024 Nobel Prize in Chemistry for Demis Hassabis and John Jumper. AlphaFold3 (Abramson et al. 2024, Nature) extends to protein-ligand complexes.\n\n=== NEUROSCIENCE CONNECTION ===\nThe most important drug target families in neuroscience ALL benefit from AlphaFold:\n\n1. ION CHANNELS: AlphaFold has predicted structures for many ion channel families. For example, the GluCl (glutamate-gated chloride channel) that Dr. Serbe-Kamp's research involves is part of the Cys-loop receptor superfamily. The crystal structure of C. elegans GluCl bound to ivermectin was solved by Hibbs & Bhatt (2007, Nature 474:54-60) and AlphaFold predicts related structures. Understanding these structures helps design better drugs.\n\n2. GPCRs (G-Protein Coupled Receptors): ~34% of all FDA-approved drugs target GPCRs. These include serotonin receptors (5-HT, targeted by antidepressants like fluoxetine/Prozac), dopamine receptors (targeted by antipsychotics like haloperidol), and opioid receptors (targeted by morphine, fentanyl). AlphaFold2 predicted structures of many GPCRs.\n\n3. NEUROTRANSMITTER TRANSPORTERS: The serotonin transporter (SERT, target of SSRIs), dopamine transporter (DAT, target of methylphenidate/Ritalin), and GABA transporters all have AlphaFold-predicted structures.\n\n4. GABA-A RECEPTORS: Targeted by benzodiazepines (Valium, Xanax), barbiturates, and general anesthetics. These are pentameric ligand-gated ion channels, same superfamily as GluCl.\n\nKey point: AlphaFold enables structure-based drug design for targets that were previously too hard to crystallize, many of which are membrane proteins critical to neuroscience.")
    n += 1
    make_section_divider(prs, "Molecular Data Types", n, notes="Transition: Now that we have seen the big picture, let us get technical. How do we actually represent molecules for a computer? We will cover SMILES, bioactivity data, and protein information.", subtitle="How do we represent molecules for computers?")
    n += 1
    make_content_slide(prs, "SMILES: Simplified Molecular-Input Line-Entry System", ["A way to write molecular structures as text strings", "Invented by David Weininger (1988), J. Chem. Inf. Comput. Sci. 28:31-36", "", "Examples (including neuroscience drugs):", "  Water: O  |  Ethanol: CCO  |  Aspirin: CC(=O)Oc1ccccc1C(=O)O", "  Caffeine: Cn1c(=O)c2c(ncn2C)n(C)c1=O  (adenosine receptor antagonist)", "  Serotonin: NCCc1c[nH]c2ccc(O)cc12  (neurotransmitter)", "  Dopamine: NCCc1ccc(O)c(O)c1  (neurotransmitter)", "  GABA: NCCCC(=O)O  (inhibitory neurotransmitter)", "  Diazepam (Valium): ClC1=CC2=C(C=C1)N(C)C(=O)CN2  (GABA-A modulator)", "", "Why SMILES matters: compact, human-readable, machine-parseable", "One molecule can have multiple valid SMILES (canonical vs. random)"], n, notes="Spend 3-4 minutes on SMILES. Key rules: atoms are letters, single bonds are implicit, double bonds =, triple bonds #, branches in parentheses, rings with number pairs. Lowercase letters mean aromatic atoms. The Weininger 1988 paper is the original reference.\n\n=== NEUROSCIENCE DRUG SMILES ===\nWe specifically include neurotransmitters and CNS drugs here because they are central to drug discovery:\n\n1. SEROTONIN (5-hydroxytryptamine, 5-HT): NCCc1c[nH]c2ccc(O)cc12\n   - An indolamine neurotransmitter. Contains an indole ring (tryptophan derivative) and an ethylamine side chain.\n   - 14 serotonin receptor subtypes (5-HT1A through 5-HT7), all GPCRs except 5-HT3 (ion channel).\n   - Drug targets: SSRIs (fluoxetine/Prozac blocks serotonin reuptake), triptans (sumatriptan for migraine), LSD (5-HT2A agonist).\n   - Ask students: can you identify the hydroxyl group (O) and the amine (N) in the SMILES?\n\n2. DOPAMINE: NCCc1ccc(O)c(O)c1\n   - A catecholamine neurotransmitter. Contains a catechol ring (two adjacent OH groups) and an ethylamine.\n   - 5 dopamine receptor subtypes (D1-D5).\n   - Drug targets: L-DOPA for Parkinson's, antipsychotics (haloperidol blocks D2), methylphenidate (Ritalin, blocks DAT).\n\n3. GABA (gamma-aminobutyric acid): NCCCC(=O)O\n   - The main inhibitory neurotransmitter in the brain. Very simple structure: 4-carbon chain with amine and carboxyl groups.\n   - GABA-A receptors are ligand-gated Cl- channels (same superfamily as GluCl that Dr. Serbe-Kamp studies!).\n   - Drug targets: benzodiazepines (diazepam/Valium, alprazolam/Xanax), barbiturates, general anesthetics (propofol), alcohol.\n\n4. DIAZEPAM (Valium): ClC1=CC2=C(C=C1)N(C)C(=O)CN2\n   - A benzodiazepine that enhances GABA-A receptor function (positive allosteric modulator).\n   - Notice the chlorine (Cl), the fused ring system, and the nitrogen atoms in the SMILES.\n\n5. CAFFEINE: Cn1c(=O)c2c(ncn2C)n(C)c1=O\n   - Adenosine receptor antagonist (blocks A1 and A2A receptors).\n   - A xanthine derivative. Students will experiment with caffeine using the SpikerBot!\n\nThe point: SMILES can represent ALL of these neuroscience-relevant molecules as simple text strings, ready for ML.")
    n += 1
    make_content_slide(prs, "Bioactivity Data: Measuring Drug-Target Interactions", ["How well does a molecule interact with its biological target?", "", "Key measures:", "  IC50 - Concentration inhibiting 50% of target activity", "  Ki - Binding affinity constant  |  EC50 - Half-maximal effective concentration", "  Kd - Dissociation constant  |  pIC50 = -log10(IC50) for easier modeling", "", "Neuroscience assay examples:", "  Patch-clamp electrophysiology: measure ion channel block (IC50 for hERG)", "  Calcium imaging: measure receptor activation (EC50 for GPCR agonists)", "  Radioligand binding: measure receptor affinity (Ki for dopamine D2)", "", "Key databases: ChEMBL (>2.4M compounds), PubChem (>110M), BindingDB", "Reference: Gaulton et al. (2017), Nucleic Acids Research 45:D986-D994"], n, notes="Spend 3-4 minutes explaining bioactivity measures.\n\n=== CORE CONCEPTS ===\nIC50 analogy: how much drug do I need to shut down 50% of the enzyme/channel/receptor? Lower IC50 = more potent. pIC50 = -log10(IC50 in M). A pIC50 of 8 means IC50 = 10nM, very potent.\n\n=== NEUROSCIENCE ASSAYS ===\nThe bioactivity data in ChEMBL comes from actual laboratory experiments. For neuroscience targets, the key assay types are:\n\n1. PATCH-CLAMP ELECTROPHYSIOLOGY:\n   - The gold standard for measuring ion channel activity.\n   - A glass micropipette (tip ~1 µm) seals onto a cell membrane, isolating a tiny patch of membrane or the whole cell.\n   - You can measure the current flowing through individual ion channels.\n   - For drug discovery: apply increasing concentrations of a drug while recording channel current. The concentration that reduces current by 50% is the IC50.\n   - This is EXACTLY what Dr. Serbe-Kamp does in his Drosophila research: recording from neurons while manipulating pharmacology or optogenetics.\n   - For hERG safety testing: patch-clamp HEK293 cells expressing hERG channels, measure block IC50.\n   - Automated patch-clamp machines (SyncroPatch, QPatch) can test thousands of compounds per day.\n\n2. CALCIUM IMAGING (two-photon, confocal):\n   - Load neurons with calcium-sensitive fluorescent dyes (GCaMP, Oregon Green BAPTA).\n   - When a neuron fires, Ca2+ floods in, increasing fluorescence.\n   - For drug screening: measure changes in calcium transient amplitude/frequency after drug application.\n   - Dr. Serbe-Kamp's 2023 J. Neurosci. paper used two-photon calcium imaging in Drosophila T4 neurons to show how voltage-to-calcium transformation enhances direction selectivity.\n   - For drug discovery: high-throughput calcium imaging (FLIPR assay) screens GPCR agonists/antagonists.\n\n3. RADIOLIGAND BINDING:\n   - Classic method to measure drug-receptor affinity.\n   - Incubate membrane preparations with a radioactive ligand, then add test compounds.\n   - The Ki (inhibition constant) reflects binding affinity.\n   - Example: measuring Ki of antipsychotics at dopamine D2 receptors. Haloperidol has Ki ~1 nM.\n\n4. FUNCTIONAL ASSAYS:\n   - cAMP assays for GPCR signaling\n   - FLIPR for calcium-mobilizing receptors\n   - GTPγS binding for G-protein activation\n\nKey point: the pIC50 values that our ML models predict ultimately come from these laboratory measurements. Understanding the assay helps you understand the data quality and biological meaning.")
    n += 1
    make_two_column_slide(prs, "Key Public Databases for Drug Discovery", "Molecular / Chemical", ["ChEMBL - curated bioactivity data", "PubChem - largest public chemistry DB", "ZINC - purchasable compounds for screening", "DrugBank - approved drug information", "MoleculeNet - benchmark datasets for ML"], "Biological / Protein", ["UniProt - protein sequences & annotation", "PDB - experimental 3D structures", "AlphaFold DB - predicted structures", "STRING - protein-protein interactions", "KEGG / Reactome - biological pathways"], n, notes="Reference slide, go through quickly in 2 minutes. Emphasize that one of the great things about drug discovery research is that so much data is publicly available. MoleculeNet (Wu et al. 2018, Chemical Science) provides standardized benchmarks. Students should bookmark ChEMBL and MoleculeNet.")
    n += 1
    make_content_slide(prs, "Biophysical Modelling & The Programmable SpikerBot", ["The SpikerBot (Backyard Brains) - record AND stimulate real neurons", "  Dr. Serbe-Kamp is Co-Director of Summer Fellowships at Backyard Brains", "", "Programmable neural motifs you will explore:", "  Tonic firing - regular spikes (motor neurons, Drosophila visual interneurons)", "  Burst firing - clustered spikes (thalamic relay, dopamine neurons)", "  Irregular / Poisson firing - random intervals (cortical neurons)", "", "From Drosophila to drug discovery:", "  Ion channels (Na+, K+, Ca2+, Cl-) are major drug targets (~18% of drugs)", "  GluCl channels (from Dr. Serbe-Kamp's fly research) = ivermectin target!", "  Hodgkin-Huxley model (1952): simulate how drugs alter channel gating", "  Connectomics: map ALL synapses -> identify new drug targets", "", "Same pipeline: neural signal -> features -> ML model -> prediction"], n, notes="DETAILED PRESENTER NOTES - BIOPHYSICAL MODELLING, SPIKERBOT & DROSOPHILA NEUROSCIENCE\n\nSpend 5-7 minutes on this slide. This bridges neuroscience, the instructor's research, and drug discovery.\n\n=== DR. SERBE-KAMP'S RESEARCH & THE SPIKERBOT ===\nDr. Serbe-Kamp is Co-Director of Summer Fellowships at Backyard Brains (backyardbrains.com), the company that makes the SpikerBox and SpikerBot. He has led international citizen science projects including:\n- 'A Library of Electrophysiological Responses in Plants' (Plant Signaling & Behavior, 2024) - students from multiple countries recorded plant electrical signals using SpikerBoxes\n- The ERGo! platform for electroretinogram recording from insect eyes - citizen science biodiversity monitoring\n- 'Authentic Research Investigations: Can Plants Learn?' - engaging students in real research\n\nThe SpikerBot extends the SpikerBox with programmable stimulation and a robotic gripper. Key hardware:\n- Electrodes for biological tissue (cockroach leg, earthworm, human EMG)\n- Amplifier (microvolt signals to measurable range)\n- ADC (analog-to-digital converter)\n- Arduino-compatible microcontroller for programmable stimulation\n- Spike Recorder app for visualization\n\n=== DROSOPHILA VISUAL NEUROSCIENCE -> DRUG TARGETS ===\nDr. Serbe-Kamp's core research is on how the Drosophila (fruit fly) brain computes visual motion. Key publications:\n\n1. 'A Directional Tuning Map of Drosophila Elementary Motion Detectors' (Maisak, Haag, Ammer, Serbe et al., 2013, Nature 500:212-216)\n   - Mapped how T4 (ON) and T5 (OFF) neurons in the fly optic lobe respond to different directions of motion.\n   - These neurons are organized in 4 layers, each tuned to one of four cardinal directions.\n   - This was the first comprehensive directional tuning map of the fly motion detection circuit.\n\n2. 'Comprehensive Characterization of the Major Presynaptic Elements to the Drosophila OFF Motion Detector' (Serbe et al., 2016, Neuron 89:829-841)\n   - Used EM connectomics, calcium imaging, electrophysiology, and optogenetics to map ALL inputs to T5 neurons.\n   - Identified specific medulla interneuron types (Tm1, Tm2, Tm4, Tm9) providing input.\n   - This is connectomics in action: mapping the complete wiring diagram of a neural circuit.\n\n3. 'Multilevel visual motion opponency in Drosophila' (Haag, Arenz, Serbe-Kamp et al., 2023, Nature Neuroscience 26:1894-1903)\n   - Discovered that GluClα (glutamate-gated chloride channel) mediates direction-opponent inhibition.\n   - A single neuron type implements inhibition at THREE different levels of the circuit.\n   - GluClα is the SAME receptor family targeted by IVERMECTIN!\n\n4. 'Voltage to Calcium Transformation Enhances Direction Selectivity in Drosophila T4 Neurons' (Serbe-Kamp et al., 2023, J. Neurosci. 43:2497-2514)\n   - Used two-photon calcium imaging + computational modeling.\n   - Showed that the nonlinear voltage-to-calcium transformation in T4 neuron dendrites enhances direction selectivity.\n\n=== THE GluCl / IVERMECTIN CONNECTION ===\nThis is the DIRECT link between Dr. Serbe-Kamp's research and drug discovery:\n\nGluCl (glutamate-gated chloride channel) is a member of the Cys-loop ligand-gated ion channel superfamily (same family as GABA-A, glycine receptors, nAChR).\n\nIvermectin was discovered by Satoshi Ōmura and William Campbell (2015 Nobel Prize in Physiology or Medicine). It is:\n- An antiparasitic drug that targets GluCl channels in nematode and arthropod neurons\n- One of the WHO Essential Medicines\n- Treats river blindness (onchocerciasis), elephantiasis (lymphatic filariasis), scabies, head lice\n- The mechanism: ivermectin binds to GluCl channels and locks them OPEN, causing an influx of Cl- ions that hyperpolarizes the neuron, paralyzing the parasite\n- In Dr. Serbe-Kamp's research, GluClα mediates inhibition in the Drosophila motion detection circuit\n\nInsecticide connection: Avermectins (the class ivermectin belongs to) are used as both DRUGS and INSECTICIDES. Abamectin is a widely used agricultural insecticide that targets the same GluCl channels in pest insects. This is a beautiful example of how basic neuroscience research (understanding ion channel function in flies) directly translates to both drug discovery AND crop protection.\n\n=== NEUROPHARMACOLOGY ON THE SPIKERBOT ===\nIon channel drugs that can be demonstrated:\n- Lidocaine (Nav blocker): apply to cockroach leg preparation, observe abolishment of action potentials\n- Caffeine (adenosine antagonist): record your own EMG before and after coffee\n- Nicotine (nAChR agonist): enhances neural excitability (DO NOT use in class, just discuss)\n\n=== THE HODGKIN-HUXLEY MODEL ===\nHodgkin & Huxley (1952), J. Physiol. 117:500-544 (Nobel Prize 1963)\nC_m * dV/dt = -g_Na * m^3 * h * (V - E_Na) - g_K * n^4 * (V - E_K) - g_L * (V - E_L) + I_ext\nDrug effects = modifying conductance parameters. We simulate this in the Week 1 notebook.\n\n=== PROGRAMMABLE NEURAL MOTIFS ===\n1. TONIC: Regular spikes. Like Drosophila lobula plate tangential cells (HS/VS cells) responding to sustained motion.\n2. BURST: Clustered spikes. Like thalamic neurons in sleep, or dopamine neurons signaling reward.\n3. IRREGULAR: Random intervals (Poisson). Like cortical neurons during wakefulness.\nStudents program the SpikerBot to generate each motif and observe the muscle response.\n\n=== CONNECTOMICS ===\nThe complete Drosophila brain connectome (FlyWire: Dorkenwald et al. 2024, Nature) is a graph with ~140,000 neurons and ~50 million synapses. This is THE dataset for Week 4's GNN concepts: neurons are nodes, synapses are edges, and GNNs can predict neuron types and function from graph structure.")
    n += 1
    make_content_slide(prs, "Introduction to RDKit", ["RDKit - open-source cheminformatics library (C++ core, Python bindings)", "Landrum, G. (2006-2024). https://www.rdkit.org", "", "What can RDKit do?", "  Parse SMILES strings into molecular objects", "  Calculate molecular properties (MW, LogP, HBD, HBA, TPSA)", "  Generate molecular fingerprints (Morgan/ECFP, RDKit, MACCS)", "  Substructure searching and molecular similarity", "  2D and 3D molecular visualization", "", "Installation: pip install rdkit", "We will use RDKit in EVERY week of this course"], n, notes="Spend 2-3 minutes on RDKit. Created by Greg Landrum at Novartis, now maintained by a large open-source community. Think of RDKit as the NumPy of chemistry. In today's practical, we will install it and use it to load molecules, calculate properties, and draw structures. RDKit converts SMILES strings into rich molecular objects that we can compute features from. This is the bridge between chemistry and machine learning.")
    n += 1
    make_content_slide(prs, "Today's Practical: Explore Molecules with RDKit", ["Open the Week 1 Jupyter Notebook: week1_introduction/Week1_Practical.ipynb", "", "What we will do:", "  1. Install and import RDKit in Google Colab", "  2. Load a molecular dataset from ChEMBL (EGFR inhibitors)", "  3. Parse SMILES and visualize molecules", "  4. Calculate molecular properties (MW, LogP, number of rings, etc.)", "  5. Plot property distributions", "  6. Compare drug-like vs. non-drug-like molecules", "", "Time: ~60 minutes", "Work in pairs - discuss what you observe!"], n, notes="Spend 2 minutes explaining the practical, then transition to the hands-on session. The notebook is designed to run in Google Colab. We use EGFR (Epidermal Growth Factor Receptor) inhibitors as our example dataset because EGFR is a well-studied cancer target with lots of data in ChEMBL. Students may have heard of drugs like gefitinib (Iressa) or erlotinib (Tarceva). Encourage students to experiment.")
    n += 1
    make_discussion_slide(prs, "If you could use AI to accelerate ANY aspect\nof drug discovery, which would you choose and why?", ["Think about: target identification, molecule design, clinical trials, safety prediction...", "Consider: what is currently the biggest bottleneck?", "Bonus: what are the risks of using AI in each area?"], n, notes="This is a 5-7 minute discussion. Let students discuss in small groups first, then share with the class. Guide the discussion toward: there is no single answer. AI helps at every stage, but the highest-impact areas are probably lead optimization (most time-consuming) and clinical trial design (most expensive). If someone mentions risks, validate that: AI can learn biases in data, predict artifacts, or create false confidence. We will dedicate time to ethics in Week 7.")
    n += 1
    make_takeaway_slide(prs, ["Drug discovery is slow (12-15 years), expensive ($2.6B), and risky (>90% failure)", "CNS drugs fail most: 99.6% failure rate for Alzheimer's drugs (2002-2012)", "AI can accelerate every stage - from target ID to clinical trials", "Real examples: Insilico Medicine, AlphaFold, Drosophila connectomics", "SMILES notation converts molecules (incl. neurotransmitters) to text", "Bioactivity data (IC50, Ki) comes from assays like patch-clamp & calcium imaging", "Neuroscience & drug discovery share the same pipeline: signal -> features -> ML", "GluCl channels: from Drosophila motion vision to ivermectin drug target"], 1, n, notes="Quickly recap each point in 2-3 minutes. Emphasize the overarching narrative: drug discovery has a problem (slow/expensive/risky), neuroscience provides critical target knowledge, AI is the tool to accelerate both fields, and this course bridges them. The GluCl example perfectly illustrates how basic neuroscience research (Drosophila visual circuits) connects to real-world drugs (ivermectin).")
